<template>
	<div class="Switch page" v-show="timer">
		<div class="top">
			<div class="auto-box btn-grey">
				<div class="col-16">
					<img class="icon" src="@/assets/img/logo-o.png" />
					<span class="nickname font-color-grey">
						{{userInfo?userInfo.nickname.slice(0,8):''}}...登录中
					</span>
					<img class="loading" src="@/assets/img/loading-red.png" />
				</div>
				<div class="col-8">
					<div class="btn bg-red btn-primary color-white" @click="switchUser">切换账号</div>
				</div>
			</div>
		</div>
	</div>
</template>

<script>
	import {
		ref
	} from 'vue'
	export default {
		name: 'Switch',
		setup() {
			return {
				loginType: ref(null),
				timer: ref(null)
			}
		},
		created() {
			if (this.loginRemember) {
				Object.assign(this, this.loginRemember)
			}

			this.go('/switch')
			//获得历史用户accessToken
			let userInfo = this.userInfo
			if (!userInfo || !this.initData || this.initData.yofiLogout) {
				if(this.loginWithoutAccount){
					return this.go('/login?showForm=1')
				}
				return this.go('/login')
			}

			this.timer = setTimeout(() => {

				this.loginAuto()
			}, 2000)
		},
		computed: {
			loginRemember() {
				return this.$store.getters['loginRemember']
			},
			loginWithoutAccount() {
				if (this.initData) {
					return this.initData.loginWithoutAccount
				}
				return true
			},
		},
		activated() {
			this.loginAuto()
		},
		methods: {
			async loginAuto() {
				if (this.loginType == null || this.userInfo == null) {
					if(this.loginWithoutAccount){
						return this.go('/login?showForm=1')
					}
					return this.go('/login')
				}

				let userInfo = this.userInfo
				let res = await this.$store.dispatch('login/loginAuto', {
					accessToken: userInfo ? userInfo.accessToken : '',
					loginType: this.loginType,
				})
				if (this.$check.ok(res)) {
					let param = Object.assign({
						loginType: this.loginType
					}, res[0].data.data)
					this.$store.commit('SET_USER_INFO', param)
					if (this.userInfo.isForceAuthentication && !this.userInfo.isAuthentication) {
						return this.go('/auth')
					}
					if (this.userInfo.isForceBindPhone && !this.userInfo.phone) {
						return this.go('/bind')
					}
					this.$bridge.postLoginSuccess('loginSuccess', param)
				} else {
					this.switchUser()
					this.$bridge.postLoginSuccess('loginFailed', res)
				}
			},
			switchUser() {
				clearTimeout(this.timer)
				this.$store.commit('SET_LOGIN_WITHOUT_ACCOUNT_LOCAL', false)
				this.go('/login')
			},
		}
	}
</script>

<style scoped>
	.Switch {
		display: table-cell;
		text-align: center;
		vertical-align: middle;
	}

	.top {
		position: fixed;
		top: 40px;
		width: 100%;
		text-align: center;
	}

	.auto-box {
		display: inline-block;
		background: #f4f2f2;
		border-radius: 6px;
		text-align: left;
	}

	.icon {
		width: 30px;
		height: 30px;
		vertical-align: middle;
	}

	.nickname {
		display: inline-block;
		height: 30px;
		line-height: 30px;
		font-size: 16px;
		padding: 3px 6px;
		vertical-align: middle;
	}

	.loading {
		width: 14px;
		height: 14px;
		vertical-align: middle;
		-webkit-animation: myRotate 3s linear infinite;
		animation: myRotate 3s linear infinite;
		object-fit: cover;
	}

	.btn {
		padding: 4px 20px;
		vertical-align: middle;
		text-align: center;
	}

	@-webkit-keyframes myRotate {
		0% {
			-webkit-transform: rotate(0deg);
		}

		50% {
			-webkit-transform: rotate(180deg);
		}

		100% {
			-webkit-transform: rotate(360deg);
		}
	}

	@keyframes myRotate {
		0% {
			-webkit-transform: rotate(0deg);
		}

		50% {
			-webkit-transform: rotate(180deg);
		}

		100% {
			-webkit-transform: rotate(360deg);
		}
	}

	@media (min-width: 420px) {
		.auto-box {
			width: 60%;
			padding: 6px 10px;
		}

		.icon {
			width: 22px;
			height: 22px;
		}

		.nickname {
			height: 20px;
			line-height: 22px;
			font-size: 14px;
		}

		.loading {
			width: 14px;
			height: 14px;
		}

	}

	@media (max-width: 420px) {
		.auto-box {
			width: 80%;
			padding: 10px;
		}

		.icon {
			width: 30px;
			height: 30px;
		}

		.nickname {
			height: 20px;
			line-height: 24px;
			font-size: 18px;
		}

		.loading {
			width: 18px;
			height: 18px;
		}
	}
</style>
